const T = {
  bg: "#F7F5F2", surface: "#FFFFFF", ink: "#111111", inkMid: "#444444", inkLight: "#888888",
  border: "#E2DDD8", brown: "#8B5E3C", brownLight: "#C4956A", brownPale: "#F0E8DF",
  red: "#C0392B", redPale: "#FDECEA", black: "#0A0A0A", success: "#2D6A4F", successPale: "#EAF4EF",
  shadow: "0 1px 12px rgba(0,0,0,0.06)", shadowMd: "0 4px 24px rgba(0,0,0,0.10)",
};
const FD = "'Baloo 2', 'Baloo Tamma 2', Georgia, sans-serif";
const FB = "'DM Mono', 'Courier New', monospace";

// ─── IN-MEMORY USER STORE (no localStorage) ───
const USERS = {};

// ─── SPLASH SCREEN ───
function SplashScreen({ name, onDone }) {
  const [phase, setPhase] = useState(0);
  useEffect(() => {
    const t1 = setTimeout(() => setPhase(1), 900);
    const t2 = setTimeout(() => setPhase(2), 2400);
    const t3 = setTimeout(() => onDone(), 3100);
    return () => [t1, t2, t3].forEach(clearTimeout);
  }, []);
  return (
    <div style={{
      position: "fixed", inset: 0, background: T.black, zIndex: 9999,
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
      animation: phase === 2 ? "splashOut 0.7s ease forwards" : "none",
      pointerEvents: "none",
    }}>
      <div style={{ position: "absolute", top: 32, left: 32, width: 48, height: 48, borderTop: `2px solid ${T.brownLight}`, borderLeft: `2px solid ${T.brownLight}`, opacity: 0.5 }} />
      <div style={{ position: "absolute", bottom: 32, right: 32, width: 48, height: 48, borderBottom: `2px solid ${T.brownLight}`, borderRight: `2px solid ${T.brownLight}`, opacity: 0.5 }} />
      <div style={{
        fontFamily: FD, fontSize: "clamp(40px, 8vw, 80px)", fontWeight: 800,
        color: "#fff", letterSpacing: "0.06em", textAlign: "center",
        animation: "nameFadeIn 0.9s cubic-bezier(0.16,1,0.3,1) forwards", lineHeight: 1.1,
      }}>{name || "FinSense"}</div>
      <div style={{ marginTop: 16, height: 2, background: T.brown, animation: "lineDraw 0.8s 0.6s ease forwards", width: 0, animationFillMode: "forwards" }} />
      {phase >= 1 && (
        <p style={{ marginTop: 20, fontFamily: FB, fontSize: 13, color: T.brownLight, letterSpacing: "0.25em", textTransform: "uppercase", animation: "subFadeIn 0.6s ease forwards" }}>
          Your Financial Intelligence
        </p>
      )}
      <div style={{ position: "absolute", bottom: 40, display: "flex", gap: 8 }}>
        {[0,1,2].map(i => <div key={i} style={{ width: 6, height: 6, borderRadius: "50%", background: T.brownLight, opacity: 0.4, animation: `pulse 1.2s ${i*0.2}s infinite` }} />)}
      </div>
    </div>
  );
}

// ─── AUTH PAGE ───
function AuthPage({ onAuth }) {
  const [mode, setMode]         = useState("login");
  const [name, setName]         = useState("");
  const [email, setEmail]       = useState("");
  const [password, setPassword] = useState("");
  const [salary, setSalary]     = useState("");
  const [error, setError]       = useState("");
  const [success, setSuccess]   = useState(false);

  const inputStyle = (focused) => ({
    width: "100%", boxSizing: "border-box",
    padding: "12px 14px",
    border: `1.5px solid ${focused ? "#111" : "#D1D5DB"}`,
    borderRadius: 8, fontFamily: FB, fontSize: 14,
    color: "#111", background: "#fff", outline: "none",
    transition: "border-color 0.15s",
  });

  const [focused, setFocused] = useState({});
  const focus   = (k) => setFocused(p => ({ ...p, [k]: true }));
  const blur    = (k) => setFocused(p => ({ ...p, [k]: false }));

  const handleSubmit = () => {
    setError("");
    if (!email.trim() || !password.trim()) { setError("Email and password are required."); return; }
    if (!email.includes("@")) { setError("Please enter a valid email address."); return; }
    if (password.length < 6) { setError("Password must be at least 6 characters."); return; }

    if (mode === "signup") {
      if (!name.trim()) { setError("Please enter your full name."); return; }
      if (USERS[email.trim()]) { setError("An account already exists with this email."); return; }
      USERS[email.trim()] = { name: name.trim(), password, salary: salary || "" };
      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        setMode("login");
        setName(""); setPassword(""); setSalary(""); setError("");
      }, 1800);
    } else {
      const user = USERS[email.trim()];
      if (!user) { setError("No account found. Please sign up first."); return; }
      if (user.password !== password) { setError("Incorrect password. Please try again."); return; }
      onAuth(user.name, email.trim(), user.salary);
    }
  };

  // Success screen after signup
  if (success) {
    return (
      <div style={{ position: "fixed", inset: 0, background: "#F9FAFB", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 999 }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ width: 64, height: 64, borderRadius: "50%", background: "#ECFDF5", border: "2px solid #6EE7B7", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 28, margin: "0 auto 20px" }}>✓</div>
          <p style={{ margin: "0 0 8px", fontFamily: FD, fontSize: 22, fontWeight: 800, color: "#111" }}>Account Created!</p>
          <p style={{ margin: 0, fontFamily: FB, fontSize: 13, color: "#6B7280" }}>Redirecting you to sign in...</p>
        </div>
      </div>
    );
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "#F3F4F6", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 999 }}>
      <div style={{ width: "100%", maxWidth: 420, background: "#fff", borderRadius: 16, border: "1px solid #E5E7EB", boxShadow: "0 4px 32px rgba(0,0,0,0.07)", padding: "36px 36px 30px" }}>

        {/* Logo */}
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 28 }}>
          <div style={{ width: 36, height: 36, background: "#111", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FD, fontWeight: 800, fontSize: 16, color: "#C4956A" }}>₹</div>
          <span style={{ fontFamily: FD, fontWeight: 800, fontSize: 18, color: "#111" }}>FinSense</span>
        </div>

        {/* Heading */}
        <p style={{ margin: "0 0 4px", fontFamily: FD, fontSize: 22, fontWeight: 800, color: "#111" }}>
          {mode === "login" ? "Sign in" : "Create account"}
        </p>
        <p style={{ margin: "0 0 24px", fontFamily: FB, fontSize: 12, color: "#9CA3AF" }}>
          {mode === "login" ? "Enter your credentials to continue" : "Fill in the details to get started"}
        </p>

        {/* FIELDS */}
        {mode === "signup" && (
          <div style={{ marginBottom: 14 }}>
            <label style={{ display: "block", fontFamily: FB, fontSize: 11, fontWeight: 600, color: "#374151", marginBottom: 6, letterSpacing: "0.04em" }}>Full Name</label>
            <input value={name} onChange={e => setName(e.target.value)}
              onFocus={() => focus("name")} onBlur={() => blur("name")}
              placeholder="Arjun Sharma"
              style={inputStyle(focused.name)} />
          </div>
        )}

        <div style={{ marginBottom: 14 }}>
          <label style={{ display: "block", fontFamily: FB, fontSize: 11, fontWeight: 600, color: "#374151", marginBottom: 6, letterSpacing: "0.04em" }}>Email Address</label>
          <input type="email" value={email} onChange={e => setEmail(e.target.value)}
            onFocus={() => focus("email")} onBlur={() => blur("email")}
            placeholder="you@example.com"
            style={inputStyle(focused.email)} />
        </div>

        <div style={{ marginBottom: mode === "signup" ? 14 : 20 }}>
          <label style={{ display: "block", fontFamily: FB, fontSize: 11, fontWeight: 600, color: "#374151", marginBottom: 6, letterSpacing: "0.04em" }}>Password</label>
          <input type="password" value={password} onChange={e => setPassword(e.target.value)}
            onFocus={() => focus("pass")} onBlur={() => blur("pass")}
            onKeyDown={e => e.key === "Enter" && handleSubmit()}
            placeholder="Min. 6 characters"
            style={inputStyle(focused.pass)} />
        </div>

        {mode === "signup" && (
          <div style={{ marginBottom: 20 }}>
            <label style={{ display: "block", fontFamily: FB, fontSize: 11, fontWeight: 600, color: "#374151", marginBottom: 6, letterSpacing: "0.04em" }}>Monthly Salary <span style={{ color: "#9CA3AF", fontWeight: 400 }}>(optional)</span></label>
            <div style={{ position: "relative" }}>
              <span style={{ position: "absolute", left: 13, top: "50%", transform: "translateY(-50%)", color: "#9CA3AF", fontFamily: FB, fontSize: 14 }}>₹</span>
              <input type="number" value={salary} onChange={e => setSalary(e.target.value)}
                onFocus={() => focus("sal")} onBlur={() => blur("sal")}
                placeholder="85000"
                style={{ ...inputStyle(focused.sal), paddingLeft: 28 }} />
            </div>
          </div>
        )}

        {/* Error */}
        {error && (
          <div style={{ background: "#FFF1F0", border: "1px solid #FFB3AE", borderRadius: 8, padding: "9px 13px", marginBottom: 16 }}>
            <p style={{ margin: 0, fontFamily: FB, fontSize: 12, color: "#C0392B" }}>⚠ {error}</p>
          </div>
        )}

        {/* Primary button */}
        <button onClick={handleSubmit}
          style={{ width: "100%", padding: "13px", background: "#111", color: "#fff", border: "none", borderRadius: 8, fontFamily: FB, fontSize: 13, fontWeight: 700, cursor: "pointer", letterSpacing: "0.06em", marginBottom: 12 }}
          onMouseOver={e => e.currentTarget.style.background = "#333"}
          onMouseOut={e => e.currentTarget.style.background = "#111"}
        >
          {mode === "login" ? "SIGN IN" : "CREATE ACCOUNT"}
        </button>

        {/* Switch mode */}
        <p style={{ margin: 0, textAlign: "center", fontFamily: FB, fontSize: 12, color: "#6B7280" }}>
          {mode === "login" ? "Don't have an account? " : "Already have an account? "}
          <span onClick={() => { setMode(mode === "login" ? "signup" : "login"); setError(""); }}
            style={{ color: "#111", fontWeight: 700, cursor: "pointer", textDecoration: "underline" }}>
            {mode === "login" ? "Sign up" : "Sign in"}
          </span>
        </p>

      </div>
    </div>
  );
}

